# joblink-kit-jobteam-py
Part of the JobLink kit. Use the joblink-kit skill to write these files out.
Copy the text between each BEGIN FILE and END FILE line exactly (no edits, no reformatting) to the
path shown, under <TEAM_DIR>/ (default /workspace/joblink-team/).

=== BEGIN FILE kit/scripts/jobteam.py ===
"""JobLink team core (generic): state store, reply parser, email composer, scam screen,
daily cap + next-weekday queue, browser lock. No personal data is stored or printed here:
the job seeker's address and saved answers are read from <BASE>/private/ only when needed.
Set JOBTEAM_BASE to the team folder (default ./job-team). Version: JobLink team kit v2.0 (JL-002)."""
import datetime as dt, fcntl, json, os, re, time
from contextlib import contextmanager
from zoneinfo import ZoneInfo

ET = ZoneInfo("America/New_York")
BASE = os.environ.get("JOBTEAM_BASE", os.path.abspath("job-team"))
def P(*a): return os.path.join(BASE, *a)
DAILY_CAP = int(os.environ.get("JOBTEAM_DAILY_CAP", "5"))
LOCK_STALE_MIN = 30
ASK_EXPIRE_DAYS = 5
FINAL = {"submitted", "no", "declined", "expired", "skipped_scam", "skipped_linkedin_only",
         "closed_posting", "failed", "skipped"}

def now_et(): return dt.datetime.now(ET)
def _ensure(d): os.makedirs(d, mode=0o700, exist_ok=True)

def _atomic_write(path, obj):
    _ensure(os.path.dirname(path))
    tmp = path + ".tmp"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as f: json.dump(obj, f, indent=1)
    os.replace(tmp, path)

@contextmanager
def _state_lock():
    _ensure(P("state"))
    fd = os.open(P("state", ".state.lock"), os.O_RDWR | os.O_CREAT, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX); yield
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN); os.close(fd)

# ---------- job state store ----------
def _jpath(job_id):
    if not re.fullmatch(r"J[SA]-\d{8}-\d{2}", job_id): raise ValueError("bad job_id")
    return P("state", "jobs", job_id + ".json")

def get_job(job_id):
    p = _jpath(job_id)
    if not os.path.exists(p): return None
    with open(p) as f: return json.load(f)

def open_job(job_id, lane, company="", title="", link="", fit=None, phone_contact=""):
    """Create a job record once. Returns (record, created). Dedupes by job_id and by link."""
    with _state_lock():
        rec = get_job(job_id)
        if rec: return rec, False
        if link:
            for f in os.listdir(P("state", "jobs")) if os.path.isdir(P("state", "jobs")) else []:
                if f.endswith(".json"):
                    o = json.load(open(P("state", "jobs", f)))
                    if o.get("link") == link or (o.get("company"), o.get("title")) == (company, title) and company:
                        return o, False
        state = {"AUTO": "yes", "CONFIRM": "open", "SCAM": "skipped_scam", "SKIP": "skipped"}[lane]
        rec = {"job_id": job_id, "lane": lane, "company": company, "title": title, "link": link,
               "fit": fit, "phone_contact": phone_contact, "state": state,
               "answered_by": "auto" if lane == "AUTO" else None, "answer_time_et": None,
               "history": [[now_et().isoformat(timespec="seconds"), "created", state]]}
        _atomic_write(_jpath(job_id), rec)
        return rec, True

def record_answer(job_id, answer, source):
    """First answer wins. answer: 'yes'|'no'; source: 'card'|'email'|'room'.
    Returns dict(result=applied|duplicate|conflict|unknown_job, state=...)."""
    assert answer in ("yes", "no") and source in ("card", "email", "room")
    with _state_lock():
        rec = get_job(job_id)
        if not rec: return {"result": "unknown_job"}
        t = now_et().isoformat(timespec="seconds")
        if rec["state"] != "open":
            first = "yes" if rec["state"] not in ("no", "declined", "expired") else "no"
            res = "duplicate" if first == answer else "conflict"
            rec["history"].append([t, f"late_{source}_{answer}", res]); _atomic_write(_jpath(job_id), rec)
            return {"result": res, "state": rec["state"], "first_by": rec.get("answered_by")}
        rec["state"] = "yes" if answer == "yes" else "no"
        rec["answered_by"], rec["answer_time_et"] = source, t
        rec["history"].append([t, f"{source}_{answer}", rec["state"]])
        _atomic_write(_jpath(job_id), rec)
        return {"result": "applied", "state": rec["state"]}

def set_state(job_id, new_state, note=""):
    with _state_lock():
        rec = get_job(job_id)
        if rec is None: raise KeyError(job_id)
        if rec["state"] == "submitted": raise RuntimeError("submitted is final")
        rec["state"] = new_state
        rec["history"].append([now_et().isoformat(timespec="seconds"), note or "set", new_state])
        _atomic_write(_jpath(job_id), rec); return rec

def expire_asks(today=None):
    today = today or now_et().date(); out = []
    d = P("state", "jobs")
    for f in sorted(os.listdir(d)) if os.path.isdir(d) else []:
        rec = json.load(open(os.path.join(d, f)))
        if rec["state"] == "open":
            made = dt.date.fromisoformat(rec["history"][0][0][:10])
            if (today - made).days >= ASK_EXPIRE_DAYS:
                set_state(rec["job_id"], "expired", "ask_expired"); out.append(rec["job_id"])
    return out

# ---------- routing ----------
ASK_FLOOR = 6            # below this: SKIP (fixed)
AUTO_LINE_DEFAULT = 8    # owner can change it (6-10) in <BASE>/config.json {"auto_line": N}

def auto_line(override=None):
    """The owner's auto line: CLI/arg override > JOBTEAM_AUTO_LINE env > config.json > 8. Must be 6-10."""
    v = override
    if v is None and os.environ.get("JOBTEAM_AUTO_LINE"): v = os.environ["JOBTEAM_AUTO_LINE"]
    if v is None and os.path.exists(P("config.json")):
        with open(P("config.json")) as f: v = json.load(f).get("auto_line")
    v = AUTO_LINE_DEFAULT if v is None else int(v)
    if not ASK_FLOOR <= v <= 10: raise ValueError("auto_line must be a whole number 6-10")
    return v

def set_auto_line(n):
    """Save the owner's auto line (6-10) to config.json. Call only on the owner's own instruction."""
    n = auto_line(int(n))
    cfg = {}
    if os.path.exists(P("config.json")):
        with open(P("config.json")) as f: cfg = json.load(f)
    cfg["auto_line"] = n; _atomic_write(P("config.json"), cfg); return n

def route(fit, phone_contact, scam_flags, line=None):
    """Lanes: SCAM | AUTO = fit >= auto line and phone_contact no | CONFIRM = fit 6 to auto line - 1,
    or phone_contact yes/unclear at fit >= 6 | SKIP = fit < 6.
    Inbound customer calls only = phone_contact yes. Outbound calls the seeker times are not phone contact."""
    if scam_flags: return "SCAM"
    fit = int(fit); line = auto_line(line)
    if fit < ASK_FLOOR: return "SKIP"
    if fit >= line and phone_contact == "no": return "AUTO"
    return "CONFIRM"

def phone_contact_from_level(contact_level):
    """Map Job Scout's contact_level to the v1.7 tag. Outbound calls the seeker times are NOT phone contact."""
    return {"none": "no", "internal": "no", "outbound_calls": "no", "inbound": "yes"}.get(contact_level, "unclear")

# ---------- scam screen ----------
SCAM_PATTERNS = {
    "asks_ssn": r"social security|\bssn\b|\bss#",
    "asks_bank": r"bank (account|details|info)|routing number|direct deposit (form|details|info)|account number",
    "equipment_payment": r"(purchase|buy|pay for)\b.{0,40}\b(equipment|laptop|software|training|starter kit)|reimburse.{0,30}check|cash (a|the) check|deposit (a|the) check",
    "chat_app_interview": r"(interview|contact|chat|reach).{0,60}\b(telegram|whatsapp|signal|google chat|hangouts|text message|via text|sms)\b|\b(telegram|whatsapp|signal|hangouts)\b.{0,60}interview",
    "id_before_offer": r"(driver'?s license|passport|photo id).{0,40}(before|to apply|upload)",
    "fee": r"(application|processing|registration) fee",
}
def scam_screen(text, company_domain=None, apply_url=None):
    t = (text or "").lower(); flags = [k for k, rx in SCAM_PATTERNS.items() if re.search(rx, t)]
    if company_domain and apply_url:
        host = re.sub(r"^https?://", "", apply_url).split("/")[0].lower()
        known_ats = ("myworkdayjobs.com", "icims.com", "greenhouse.io", "lever.co", "taleo.net",
                     "successfactors.com", "smartrecruiters.com", "ultipro.com", "adp.com", "jobvite.com")
        if not (host.endswith(company_domain.lower()) or any(host.endswith(a) for a in known_ats)):
            flags.append("apply_domain_mismatch")
    return flags

# ---------- locked subjects (the seeker's mail rules sort by subject) ----------
SUBJ_DAILY = "Daily Job Updates"    # Job Scout daily email
SUBJ_ASK = "Should we apply?"       # Job Applier asks AND clarifications / new-question asks
LOCKED_SUBJECTS = (SUBJ_DAILY, SUBJ_ASK)

class SubjectGuardError(Exception): pass

def guard_send(to_addr, subject, expected=None):
    """Shared send guard. Call immediately before ANY email send by Job Scout, Job Applier or JobLink.
    Refuses: any recipient other than the address in private/recipient.json (key seeker_email), and any subject that
    does not START with one of the two locked strings (exact case, no 'Re:' prefix on our sends).
    Returns True or raises SubjectGuardError. Never prints the address."""
    exp = (expected or _recipient()).lower()
    if (to_addr or "").strip().lower() != exp:
        raise SubjectGuardError("recipient is not the approved recipient; job bots email no one else")
    if not isinstance(subject, str) or not subject.startswith(LOCKED_SUBJECTS):
        raise SubjectGuardError("subject must start with 'Daily Job Updates' or 'Should we apply?'")
    if "\n" in subject or "\r" in subject:
        raise SubjectGuardError("subject has a line break")
    return True

def daily_subject(day): return f"{SUBJ_DAILY} - {day.isoformat()}"

# ---------- numbered email composer ----------
def _new_ref():
    import secrets
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    while True:
        ref = "".join(secrets.choice(alphabet) for _ in range(4))
        if not os.path.exists(P("state", "asks", ref + ".json")): return ref

def compose_ask(jobs, day=None, write=True):
    """jobs: list of dicts company,title,pay,hours,phone_contact,phone_reason,link,job_id.
    Returns (ref, subject, body). Subject: 'Should we apply? Jobs 1-N - YYYY-MM-DD - ref XXXX'.
    Never includes any recipient address."""
    day = day or now_et().date(); ref = _new_ref() if write else "TEST"
    n = len(jobs)
    subject = f"{SUBJ_ASK} Jobs 1-{n} - {day.isoformat()} - ref {ref}"
    lines = ["This is the ONLY email to answer with job numbers. Numbers below are for this email only.", ""]
    for k, j in enumerate(jobs, 1):
        pc = j.get("phone_contact", "unclear")
        lines += [f"Job {k}", f"Company: {j.get('company') or 'not stated'}", f"Position: {j.get('title') or 'not stated'}",
                  f"Pay: {j.get('pay') or 'not stated'}", f"Hours/Schedule: {j.get('hours') or 'not stated'}",
                  f"Phone contact: {pc}" + (f" - {j['phone_reason']}" if j.get("phone_reason") else ""),
                  f"Link: {j.get('link')}", ""]
    lines += ["Reply with the job numbers you want, e.g. 'Jobs 1, 3'. Reply 'none' to skip all.", f"ref {ref}"]
    body = "\n".join(lines)
    if write:
        _atomic_write(P("state", "asks", ref + ".json"),
                      {"ref": ref, "subject": subject, "created_et": now_et().isoformat(timespec="seconds"),
                       "map": {str(k): j["job_id"] for k, j in enumerate(jobs, 1)}})
    return ref, subject, body

def compose_clarify(ref, reason):
    """Clarifying email for an ambiguous reply. Same locked prefix + same ref."""
    a = load_ask(ref); n = len(a["map"]) if a else 0
    subject = f"{SUBJ_ASK} Please confirm - ref {ref}"
    body = (f"I couldn't read your last reply for sure ({reason}), so I haven't applied to anything from it.\n"
            f"Please reply with the job numbers (1-{n}) from the email with ref {ref}, e.g. 'Jobs 1, 3', or 'none'.\nref {ref}")
    return subject, body

def compose_question(ref, job_label, question):
    """New application question for the seeker. Locked prefix; answers are saved to private/ only."""
    return (f"{SUBJ_ASK} Question for {job_label} - ref {ref}",
            f"The application for {job_label} asks:\n\n{question}\n\nReply with your answer. I'll save it for future applications.\nref {ref}")

def load_ask(ref):
    p = P("state", "asks", ref + ".json")
    if not os.path.exists(p): return None
    with open(p) as f: return json.load(f)

# ---------- reply filter + parser ----------
def _recipient():
    with open(P("private", "recipient.json")) as f: d = json.load(f)
    if isinstance(d, dict) and isinstance(d.get("seeker_email"), str): return d["seeker_email"].strip().lower()
    for v in (d.values() if isinstance(d, dict) else [d]):
        if isinstance(v, str) and "@" in v: return v.strip().lower()
    raise ValueError("no address in recipient.json")

REF_RX = re.compile(r"\bref\s+([A-Z2-9]{4})\b")
def is_our_reply(from_addr, subject, expected=None):
    """Read a message ONLY if sender == recipient.json address AND subject starts with
    'Should we apply?' (optionally after Re:/RE:/Fwd: prefixes) AND carries a known ref."""
    exp = (expected or _recipient()).lower()
    m = re.search(r"<([^>]+)>", from_addr or ""); addr = (m.group(1) if m else (from_addr or "")).strip().lower()
    if addr != exp: return None
    subj = re.sub(r"^\s*((re|fw|fwd|aw)\s*(\[\d+\])?\s*:\s*)+", "", subject or "", flags=re.I)
    if not subj.startswith(SUBJ_ASK): return None
    r = REF_RX.search(subj)
    if not r: return None
    return r.group(1) if load_ask(r.group(1)) else None

INSTRUCTION_RX = re.compile(r"social security|\bssn\b|bank|routing|password|ignore (all|previous|the above)|"
                            r"you are|system prompt|forward|upload|send (my|her|the)", re.I)
WORDNUM = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10}

def strip_quoted(text):
    out = []
    for ln in (text or "").splitlines():
        s = ln.strip()
        if s.startswith(">"): continue
        if re.match(r"^(on .+wrote:|-+ ?original message|from: |sent from my)", s, re.I): break
        out.append(ln)
    return "\n".join(out).strip()

def parse_reply(text, n_jobs, room=False):
    """Returns {'yes':[..],'no':[..]} or {'ambiguous': reason}. Never guesses.
    room=True expects the owner's 'Apply 1, 3' / 'Apply none' / 'Apply all'."""
    t = strip_quoted(text)
    if not t: return {"ambiguous": "empty reply"}
    if INSTRUCTION_RX.search(t): return {"ambiguous": "reply contains an instruction or sensitive request; ignored, ask the owner", "flag": "instruction"}
    low = t.lower()
    if room:
        m = re.match(r"^\s*apply\b(.*)$", low, re.S)
        if not m: return {"ambiguous": "room message does not start with 'Apply'"}
        low = m.group(1)
    for w, n in WORDNUM.items(): low = re.sub(rf"\b{w}\b", str(n), low)
    allj = list(range(1, n_jobs + 1))
    nums_all = [int(x) for x in re.findall(r"\d+", low)]
    NEG = r"\b(?:but not|except|not|skip|no to|no for|without|no(?=\s*(?:job\s*)?#?\d))\b"
    has_neg = re.search(NEG, low)
    if not nums_all:
        if re.search(r"\b(none|no thanks|no to all|skip all|none of them)\b|^\s*no\.?\s*$", low): return {"yes": [], "no": allj}
        if re.search(r"\b(all|every|yes to all|all of them)\b", low): return {"yes": allj, "no": []}
        if re.search(r"^\s*(yes|yep|sure|ok)\.?!?\s*$", low) and n_jobs == 1: return {"yes": [1], "no": []}
        return {"ambiguous": "no job numbers found"}
    bad = [x for x in nums_all if x < 1 or x > n_jobs]
    if bad: return {"ambiguous": f"job number(s) {bad} not in this email (1-{n_jobs})"}
    if re.search(r"\bnone\b", low): return {"ambiguous": "numbers and 'none' together"}
    if re.search(r"\b(maybe|not sure|unsure|possibly|might|depends)\b|\?", low): return {"ambiguous": "hedged reply"}
    if has_neg:
        m = re.split(NEG, low, maxsplit=1)
        yes_part, no_part = m[0], m[1]
        yes = sorted({int(x) for x in re.findall(r"\d+", yes_part)})
        no = sorted({int(x) for x in re.findall(r"\d+", no_part)})
        if re.search(r"\ball\b", yes_part) and not yes: yes = [j for j in allj if j not in no]
        if set(yes) & set(no) or not no: return {"ambiguous": "contradictory yes/no"}
        if not yes and not re.search(r"\b(only|just)\b", yes_part): return {"yes": [], "no": no, "open": [j for j in allj if j not in no]}
        return {"yes": yes, "no": no}
    return {"yes": sorted(set(nums_all)), "no": []}

# ---------- daily cap + next-weekday queue ----------
def next_weekday(d):
    d = d + dt.timedelta(days=1)
    while d.weekday() >= 5: d += dt.timedelta(days=1)
    return d

def submitted_on(day):
    d = P("state", "jobs"); n = 0
    for f in os.listdir(d) if os.path.isdir(d) else []:
        rec = json.load(open(os.path.join(d, f)))
        for t, ev, st in rec["history"]:
            if st == "submitted" and t[:10] == day.isoformat(): n += 1
    return n

def schedule_slot(job_id, day=None):
    """Return the date this job may be submitted, keeping <= DAILY_CAP per weekday (ET)."""
    day = day or now_et().date()
    with _state_lock():
        qp = P("state", "queue", "queue.json")
        q = json.load(open(qp)) if os.path.exists(qp) else {}
        if job_id in q: return dt.date.fromisoformat(q[job_id])
        d = day if day.weekday() < 5 else next_weekday(day)
        while submitted_on(d) + sum(1 for v in q.values() if v == d.isoformat()) >= DAILY_CAP:
            d = next_weekday(d)
        q[job_id] = d.isoformat(); _atomic_write(qp, q); return d

# ---------- browser lock ----------
LOCK = lambda: P("state", "browser.lock")
def acquire_browser(job_id):
    """One computerUse browser at a time. Returns ('acquired',None) | ('busy',info) | ('stale',info).
    A stale lock is reported, never silently taken."""
    _ensure(P("state"))
    try:
        fd = os.open(LOCK(), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        info = json.load(open(LOCK()))
        age = (time.time() - info["t"]) / 60
        return ("stale" if age > LOCK_STALE_MIN else "busy"), dict(info, age_min=round(age, 1))
    with os.fdopen(fd, "w") as f: json.dump({"job_id": job_id, "t": time.time(), "pid": os.getpid()}, f)
    return "acquired", None

def release_browser(job_id):
    if os.path.exists(LOCK()):
        if json.load(open(LOCK())).get("job_id") != job_id: raise RuntimeError("lock held by another job")
        os.remove(LOCK())

def clear_stale_lock():
    """Only after the owner confirms the old session is dead."""
    if os.path.exists(LOCK()): os.remove(LOCK())

# ---------- CLI for the bots (prints no PII) ----------
if __name__ == "__main__":
    import argparse, sys
    ap = argparse.ArgumentParser(prog="jobteam")
    sp = ap.add_subparsers(dest="cmd", required=True)
    g = sp.add_parser("guard", help="exit 0 only if sending SUBJECT to the approved recipient is allowed")
    g.add_argument("--subject", required=True); g.add_argument("--to", help="default: the approved recipient")
    c = sp.add_parser("compose-ask"); c.add_argument("jobs_json", help="file with a list of job dicts")
    pr = sp.add_parser("parse"); pr.add_argument("--from", dest="frm", required=True); pr.add_argument("--subject", required=True)
    pr.add_argument("body_file"); pr.add_argument("--room", action="store_true")
    a = sp.add_parser("answer"); a.add_argument("job_id"); a.add_argument("yes_no"); a.add_argument("source")
    o = sp.add_parser("open"); o.add_argument("job_id"); o.add_argument("--fit", type=int, required=True)
    o.add_argument("--phone", required=True); o.add_argument("--scam", default=""); o.add_argument("--company", default="")
    o.add_argument("--title", default=""); o.add_argument("--link", default="")
    o.add_argument("--auto-line", type=int, default=None, help="override the owner's auto line (6-10)")
    al = sp.add_parser("auto-line", help="show, or (owner's instruction only) set, the auto line")
    al.add_argument("value", nargs="?", type=int)
    s = sp.add_parser("state"); s.add_argument("job_id"); s.add_argument("new_state", nargs="?")
    l = sp.add_parser("lock"); l.add_argument("action", choices=["acquire", "release"]); l.add_argument("job_id")
    q = sp.add_parser("slot"); q.add_argument("job_id")
    sp.add_parser("expire")
    x = ap.parse_args()
    out = None
    try:
        if x.cmd == "guard":
            out = {"allowed": guard_send(x.to or _recipient(), x.subject)}
        elif x.cmd == "compose-ask":
            ref, subj, body = compose_ask(json.load(open(x.jobs_json))); out = {"ref": ref, "subject": subj, "body": body}
        elif x.cmd == "parse":
            body = open(x.body_file).read()
            if x.room:
                n = None  # room fallback reads against the newest ask
                asks = sorted(os.listdir(P("state", "asks")), key=lambda f: os.path.getmtime(P("state", "asks", f)))
                ref = asks[-1][:-5] if asks else None
            else:
                ref = is_our_reply(x.frm, x.subject)
            if not ref: out = {"ignored": True}
            else:
                amap = load_ask(ref)["map"]; r = parse_reply(body, len(amap), room=x.room)
                r["ref"] = ref
                if "ambiguous" not in r:
                    r["yes_ids"] = [amap[str(i)] for i in r["yes"]]; r["no_ids"] = [amap[str(i)] for i in r["no"]]
                out = r
        elif x.cmd == "answer": out = record_answer(x.job_id, x.yes_no, x.source)
        elif x.cmd == "open":
            flags = [f for f in x.scam.split(",") if f]; lane = route(x.fit, x.phone, flags, x.auto_line)
            rec, created = open_job(x.job_id, lane, x.company, x.title, x.link, x.fit, x.phone)
            out = {"lane": rec["lane"], "state": rec["state"], "created": created, "job_id": rec["job_id"]}
        elif x.cmd == "state":
            out = set_state(x.job_id, x.new_state) if x.new_state else get_job(x.job_id)
        elif x.cmd == "lock":
            out = {"result": acquire_browser(x.job_id)} if x.action == "acquire" else (release_browser(x.job_id) or {"released": True})
        elif x.cmd == "slot": out = {"date": schedule_slot(x.job_id).isoformat()}
        elif x.cmd == "expire": out = {"expired": expire_asks()}
        elif x.cmd == "auto-line":
            out = {"auto_line": set_auto_line(x.value) if x.value is not None else auto_line()}
    except ValueError as e:
        print(json.dumps({"error": str(e)})); sys.exit(2)
    except SubjectGuardError as e:
        print(json.dumps({"allowed": False, "reason": str(e)})); sys.exit(2)
